from pathlib import Path
import re

ROOT=Path('.')

def read(p): return (ROOT/p).read_text()
def write(p,s): (ROOT/p).write_text(s)
def rep(p,old,new,count=1):
    s=read(p)
    if old not in s: raise SystemExit(f'MISSING REPLACEMENT in {p}: {old[:120]!r}')
    if count is not None and s.count(old)<count: raise SystemExit(f'COUNT in {p}: {old[:80]!r}')
    s=s.replace(old,new,count if count is not None else -1)
    write(p,s)

def insert_before(p,marker,text):
    s=read(p)
    if marker not in s: raise SystemExit(f'MISSING MARKER {p}: {marker[:100]!r}')
    write(p,s.replace(marker,text+marker,1))

def splice(p,start,end,replacement):
    s=read(p); a=s.find(start)
    if a<0: raise SystemExit(f'MISSING START {p}: {start[:100]!r}')
    b=s.find(end,a+len(start))
    if b<0: raise SystemExit(f'MISSING END {p}: {end[:100]!r}')
    write(p,s[:a]+replacement+s[b:])

